Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define ff first
#define ss second
#define fastio ios_base::sync_with_stdio(0); cin.tie(0)
typedef long long ll;
typedef long double ld;
const ld pi = 3.141592654;
const ll N = 1000500;
const ll mod = 1000000007;
const ll maxi2 = 1e9;
using namespace std;

#define TRACE
#ifdef TRACE
#define trace(...) __f(#__VA_ARGS__, __VA_ARGS__)
template <typename Arg1>
void __f(const char* name, Arg1&& arg1) {
  cerr << name << " : " << arg1 << endl;}

template <typename Arg1, typename... Args>
void __f(const char* names, Arg1&& arg1, Args&&... args) {
  const char* comma = strchr(names + 1, ',');
  cerr.write(names, comma - names) << " : " << arg1<<" | ";
  __f(comma+1, args...);}
#else
#define trace(...)
#endif

ll repe[N];
ll used[N];
ll mult[N];

ll doit(ll i, ll k, ll n){
	ll cant = 0;

	while(1){
		if(used[i]) break;
		used[i] = true;
		i = (i * k) % n;
		cant++;
	}

	return cant;
}

ll bipow(ll a, ll b){
	if(b == 0) return 1;

	ll ans = bipow(a, b / 2);

	if(b % 2 == 0) return (ans * ans) % mod;
	else return (a * ((ans * ans) % mod)) % mod;
}

int main(){
	fastio;
	ll n, k;
	scanf("%lld %lld",&n,&k);

	if(k == 0){
		cout << bipow(n, n - 1) << endl;
		return 0;
	}

	for(ll i = 0; i < n; i++){
		if(!used[i]) {
			ll w = doit(i, k, n);
			//trace(w);
			repe[w]++;
		}
	}

	for(ll i = 1; i <= n; i++){
		for(ll j = i; j <= n; j += i){
			if(repe[j] != 0) mult[j] += repe[i] * i;
		}
	}

	//for(ll i = 1; i <= n; i++) trace(repe[i], mult[i]);
	ll ans = 1;
	for(ll i = 1; i <= n; i++){

		if(mult[i] != 0) ans = (ans * bipow(mult[i], repe[i])) % mod;
	}

	printf("%lld\n", ans);
	return 0;
}
